<?php
/**
 * Generated by hostlesswp. Do not edit on the Worker; rerun `npx hostlesswp deploy` instead.
 *
 * Settings and secrets come from the Worker env, which the runtime writes to /internal/shared/hostlesswp-env.json
 * on every boot. Database credentials live in the Hyperdrive config, not here.
 */
function hostlesswp_env( $key ) {
	static $env = null;
	if ( null === $env ) {
		$raw = @file_get_contents( '/internal/shared/hostlesswp-env.json' );
		$env = $raw ? json_decode( $raw, true ) : array();
	}
	return isset( $env[ $key ] ) ? (string) $env[ $key ] : false;
}

define( 'DB_NAME', '{{DB_NAME}}' );
define( 'DB_USER', 'hyperdrive' );
define( 'DB_PASSWORD', '' );
define( 'DB_HOST', 'hyperdrive' );
define( 'DB_CHARSET', '{{DB_CHARSET}}' );
define( 'DB_COLLATE', '{{DB_COLLATE}}' );

// The site's own keys and salts (copied from its wp-config.php into the WP_SALTS secret), so existing
// logins and nonces stay valid after the move.
$hostlesswp_salts = json_decode( hostlesswp_env( 'WP_SALTS' ) ?: '{}', true );
foreach ( array( 'AUTH_KEY', 'SECURE_AUTH_KEY', 'LOGGED_IN_KEY', 'NONCE_KEY', 'AUTH_SALT', 'SECURE_AUTH_SALT', 'LOGGED_IN_SALT', 'NONCE_SALT' ) as $hostlesswp_k ) {
	if ( empty( $hostlesswp_salts[ $hostlesswp_k ] ) ) {
		die( 'hostlesswp: WP_SALTS secret is missing ' . $hostlesswp_k . '. Run `npx hostlesswp deploy` again.' );
	}
	define( $hostlesswp_k, $hostlesswp_salts[ $hostlesswp_k ] );
}
unset( $hostlesswp_salts, $hostlesswp_k );

$table_prefix = '{{TABLE_PREFIX}}';

// The site answers on whatever host the Worker is reached by (workers.dev while testing, your domain later),
// without rewriting siteurl/home in the database.
$hostlesswp_https  = ( $_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '' ) === 'https' || ( ! empty( $_SERVER['HTTPS'] ) && 'off' !== $_SERVER['HTTPS'] );
$hostlesswp_origin = ( $hostlesswp_https ? 'https://' : 'http://' ) . ( $_SERVER['HTTP_HOST'] ?? 'localhost' );
define( 'WP_HOME', $hostlesswp_origin );
define( 'WP_SITEURL', $hostlesswp_origin );
if ( $hostlesswp_https ) {
	$_SERVER['HTTPS'] = 'on';
}
unset( $hostlesswp_origin, $hostlesswp_https );

define( 'DISABLE_WP_CRON', true );
define( 'AUTOMATIC_UPDATER_DISABLED', true );
define( 'WP_AUTO_UPDATE_CORE', false );
define( 'DISALLOW_FILE_MODS', true );
define( 'FS_METHOD', 'direct' );
// load-scripts.php reads every script from disk, but most of wp-includes/js is only a static asset (not in the
// PHP bundle), so concatenated admin scripts would come back empty. Load them as separate static files instead.
define( 'CONCATENATE_SCRIPTS', false );
define( 'WP_DEBUG', hostlesswp_env( 'WP_DEBUG' ) === '1' );
define( 'WP_DEBUG_DISPLAY', false );
define( 'WP_DEBUG_LOG', '/tmp/php-errors.log' );
@ini_set( 'display_errors', '0' );
{{EXTRA_DEFINES}}
if ( ! defined( 'ABSPATH' ) ) {
	define( 'ABSPATH', __DIR__ . '/' );
}
require_once ABSPATH . 'wp-settings.php';
